begin;
insert into auth.users(id,email,raw_user_meta_data,raw_app_meta_data,created_at,updated_at) values('f3160000-0000-4000-8000-000000000001','t16-test@example.invalid','{}','{}',now(),now());
select set_config('request.jwt.claim.sub','f3160000-0000-4000-8000-000000000001',true);
do $$declare inv jsonb;eid uuid;v integer:=1;g jsonb;r jsonb;state jsonb;schedule jsonb;ties jsonb:='{}';pair text;begin
 select jsonb_build_object('sourceUrl','https://example.invalid/t16-test','selectedModeCode','T16b','title','T16 test','playingTargetPoints','100','playingTargetInnings','20','participants',jsonb_agg(jsonb_build_object('number',i,'name','Spieler '||i,'passNo',i))) into inv from generate_series(1,9) i;
 eid:=public.create_t15_result_event(inv);state:=public.get_t15_result_event(eid);schedule:=state->'schedule';
 if jsonb_array_length(schedule)<>16 or jsonb_array_length(state->'standings'->'C')<>3 then raise exception 'T16: missing games or group C';end if;
 if public.result_mode('T16b')->'A'<>'[1,4,9]' or public.result_mode('T16b')->'B'<>'[2,5,8]' or public.result_mode('T16b')->'C'<>'[3,6,7]' then raise exception 'Wrong groups';end if;
 if exists(select 1 from jsonb_array_elements(schedule) where value->>'stage'='final' and (value->>'ready')::boolean) then raise exception 'Premature finals';end if;
 for g in select value from jsonb_array_elements(schedule) where value->>'stage'<>'final' loop
  r:=jsonb_build_object('score1',case when (g->>'seed1')::int<(g->>'seed2')::int then 100 else 3*(g->>'seed1')::int end,'score2',case when (g->>'seed2')::int<(g->>'seed1')::int then 100 else 3*(g->>'seed2')::int end,'innings1',10,'innings2',10,'high1',10,'high2',10);
  v:=public.save_t15_result(eid,g->>'key',r,v);
  ties:=ties||jsonb_build_object(g->>'key',jsonb_build_object('score1',case when (g->>'seed1')::int<(g->>'seed2')::int then 100 else 50 end,'score2',case when (g->>'seed1')::int<(g->>'seed2')::int then 50 else 100 end,'innings1',10,'innings2',10,'high1',10,'high2',10));
 end loop;
 state:=public.get_t15_result_event(eid);
 if exists(select 1 from jsonb_array_elements((state->'standings'->'A')||(state->'standings'->'B')||(state->'standings'->'C')) where value->>'played'<>'2') then raise exception 'Need two group games per player';end if;
 r:=public.t16b_position_ranking(inv,state->'results',2);
 if r->0->>'seed'<>'6' then raise exception 'GD must select best runner-up: %',r;end if;
 select value into g from jsonb_array_elements(state->'schedule') where value->>'key'='HF1';
 if g->>'seed2'<>'6' or g->>'seed1'='3' or not(g->>'ready')::boolean then raise exception 'Wrong best runner-up or own-group rematch';end if;
 select value into g from jsonb_array_elements(state->'schedule') where value->>'key'='P8';
 if g->>'seed1'<>'8' or g->>'seed2'<>'7' then raise exception 'Wrong P8';end if;
 r:='{"score1":100,"score2":50,"innings1":10,"innings2":10,"high1":10,"high2":10}';
 foreach pair in array array['HF1','HF2','P8','P5','P7','P3','F'] loop v:=public.save_t15_result(eid,pair,r,v);end loop;
 state:=public.get_t15_result_event(eid);
 select value into g from jsonb_array_elements(state->'schedule') where value->>'key'='P7';
 if g->>'seed1'<>'9' or g->>'seed2'<>'8' then raise exception 'Wrong best third or P8 winner';end if;
 v:=public.set_t15_status(eid,'completed',v);
 if (select count(*) from jsonb_object_keys((public.get_t15_result_event(eid))->'results'))<>16 then raise exception 'Incomplete result set';end if;
 v:=public.set_t15_status(eid,'open',v);
 begin perform public.save_t15_result(eid,'P8',null,v);raise exception 'P8 correction silently lost P7';exception when others then if position('DEPENDENTS_EXIST' in sqlerrm)=0 then raise;end if;end;
 v:=public.save_t15_result(eid,'P8',null,v,true);
 state:=public.get_t15_result_event(eid);if state->'results' ? 'P7' then raise exception 'P7 retained';end if;
 v:=public.save_t15_result(eid,'C1',null,v,true);state:=public.get_t15_result_event(eid);
 if exists(select 1 from jsonb_array_elements(state->'schedule') where value->>'stage'='final' and state->'results' ? (value->>'key')) then raise exception 'Group C correction retained finals';end if;
 if exists(select 1 from jsonb_array_elements(public.result_schedule(inv,ties)) where value->>'stage'='final' and (value->>'ready')::boolean) then raise exception 'Equal PP/GD/HS must not arbitrarily qualify runner-up';end if;
 ties:=jsonb_set(ties,'{C3,high2}','20');
 r:=public.t16b_position_ranking(inv,ties,2);
 if r->0->>'seed'<>'6' then raise exception 'HS must break equal PP/GD';end if;
 ties:=jsonb_set(ties,'{C2,score1}','50');ties:=jsonb_set(ties,'{C2,score2}','100');
 r:=public.t16b_position_ranking(inv,ties,2);
 if r->0->>'seed'='6' then raise exception 'PP must precede GD/HS';end if;

 begin perform public.change_result_mode(eid,'T16',v,false);raise exception 'Results silently erased';exception when others then if position('RESET_REQUIRED' in sqlerrm)=0 then raise;end if;end;
 v:=public.change_result_mode(eid,'T16',v,true);state:=public.get_t15_result_event(eid);
 if state->'snapshot'->>'selectedModeCode'<>'T16' or state->'results'<>'{}'::jsonb or jsonb_array_length(state->'standings'->'A')<>5 then raise exception 'Independent switch failed';end if;
 begin perform public.change_result_mode(eid,'T18',v);raise exception 'Wrong count accepted';exception when others then if position('Teilnehmerzahl' in sqlerrm)=0 then raise;end if;end;
 inv:=inv||jsonb_build_object('sourceUrl','https://example.invalid/t16b-independent');
 eid:=public.create_t15_result_event(inv);v:=1;
 v:=public.change_result_mode(eid,'T16',v);
 v:=public.update_result_from_invitation(eid,inv,v);
 state:=public.get_t15_result_event(eid);
 if state->'snapshot'->>'selectedModeCode'<>'T16' then raise exception 'Draft overrode independent mode';end if;
 perform public.result_sync_sent_invitation(inv,auth.uid());state:=public.get_t15_result_event(eid);v:=(state->>'version')::integer;
 if state->'snapshot'->>'selectedModeCode'<>'T16' then raise exception 'Sent invitation overrode independent mode';end if;
 v:=public.refresh_t15_event_data(eid,inv,v);state:=public.get_t15_result_event(eid);
 if state->'snapshot'->>'selectedModeCode'<>'T16' then raise exception 'Reload overrode independent mode';end if;
 begin perform public.change_result_mode(eid,'T16b',v-1);raise exception 'Stale mode update accepted';exception when others then if position('VERSION_CONFLICT' in sqlerrm)=0 then raise;end if;end;
 update public.user_roles set role='admin' where user_id=auth.uid();
 update public.tournament_operation_tables set event_id=null,assignment=null,last_seen=now();
 update public.result_events set snapshot=snapshot||'{"tableIds":["tb01","tb02"]}' where id=eid;
 perform public.tournament_operation('start',null,eid);
 begin perform public.change_result_mode(eid,'T16b',v);raise exception 'Active mode change accepted';exception when others then if position('Displaybetrieb' in sqlerrm)=0 then raise;end if;end;
 perform public.tournament_operation('stop',null,eid);
 v:=public.change_result_mode(eid,'T16b',v);state:=public.get_t15_result_event(eid);
 if jsonb_array_length(state->'standings'->'C')<>3 then raise exception 'Return to T16b failed';end if;
end $$;
select 'PASS: T16b and independent mode changes, confirmations, invitation isolation, version/active guards, group C, exact groups, 9 group games + 7 finals, PP/GD/HS qualification, cross-group semifinal, P8/P7 dependency, full completion, group C corrections and ties' result;
rollback;
